FROM attendance_evidence_subject_lock
WHERE company_id = #{companyId}
  AND employee_id = #{employeeId}
FOR UPDATE

SELECT raw_attendance_fact_id, attendance_source_id, company_id,
       fact_kind, source_business_key, source_version,
       stable_fingerprint, source_time_text, source_time_zone,
       source_instant, interval_start, interval_end,
       canonical_payload_digest, raw_object_ref, request_id,
       received_at, created_by
FROM raw_attendance_fact
WHERE attendance_source_id = #{sourceId}
  AND source_business_key = #{sourceBusinessKey}
  AND source_version = #{sourceVersion}

SELECT raw.source_business_key AS sourceBusinessKey, raw.raw_attendance_fact_id AS rawAttendanceFactId, raw.fact_kind AS factKind, normalized.normalized_attendance_record_id AS normalizedAttendanceRecordId, normalized.validation_status AS validationStatus, normalized.record_kind AS recordKind, document.oa_attendance_document_id AS oaAttendanceDocumentId, document.document_type AS documentType, CASE WHEN document.attendance_source_id = raw.attendance_source_id AND document.source_business_key = raw.source_business_key AND document.source_version = raw.source_version THEN TRUE ELSE FALSE END AS documentIdentityConsistent, matched.match_status AS matchStatus, employee.employee_id AS employeeId, employee.company_id AS employeeCompanyId, employee.employee_number AS employeeNumber, employee_history.employee_number AS historicalEmployeeNumber, CASE WHEN EXISTS ( SELECT 1 FROM attendance_report_oa_fact prior_fact JOIN oa_attendance_document prior_document ON prior_document.oa_attendance_document_id = prior_fact.oa_attendance_document_id WHERE prior_fact.company_id = #{targetCompanyId} AND prior_document.attendance_source_id = raw.attendance_source_id AND prior_document.source_business_key = raw.source_business_key ) OR EXISTS ( SELECT 1 FROM evidence_link linked WHERE linked.raw_attendance_fact_id = raw.raw_attendance_fact_id ) THEN TRUE ELSE FALSE END AS hasTargetReportFact FROM raw_attendance_fact raw LEFT JOIN normalized_attendance_record normalized ON normalized.raw_attendance_fact_id = raw.raw_attendance_fact_id LEFT JOIN oa_attendance_document document ON document.normalized_attendance_record_id = normalized.normalized_attendance_record_id LEFT JOIN employee_match_decision matched ON matched.normalized_attendance_record_id = normalized.normalized_attendance_record_id LEFT JOIN employee employee ON employee.employee_id = matched.employee_id LEFT JOIN employee_version employee_history ON employee_history.employee_id = employee.employee_id WHERE raw.attendance_source_id = #{sourceId} AND raw.source_business_key IN
#{key}
ORDER BY raw.source_business_key, raw.raw_attendance_fact_id, normalized.normalized_attendance_record_id, employee_history.employee_version_id

SELECT raw.source_business_key AS sourceBusinessKey, raw.raw_attendance_fact_id AS rawAttendanceFactId, raw.fact_kind AS factKind, normalized.normalized_attendance_record_id AS normalizedAttendanceRecordId, normalized.validation_status AS validationStatus, normalized.record_kind AS recordKind, document.oa_attendance_document_id AS oaAttendanceDocumentId, document.document_type AS documentType, CASE WHEN document.attendance_source_id = raw.attendance_source_id AND document.source_business_key = raw.source_business_key AND document.source_version = raw.source_version THEN TRUE ELSE FALSE END AS documentIdentityConsistent, matched.match_status AS matchStatus, employee.employee_id AS employeeId, employee.company_id AS employeeCompanyId, employee.employee_number AS employeeNumber, employee_history.employee_number AS historicalEmployeeNumber, CASE WHEN EXISTS ( SELECT 1 FROM attendance_report_oa_fact prior_fact JOIN oa_attendance_document prior_document ON prior_document.oa_attendance_document_id = prior_fact.oa_attendance_document_id WHERE prior_fact.company_id = #{targetCompanyId}
AND prior_fact.employee_id IN
#{employeeId}
AND 1 = 0
AND prior_document.attendance_source_id = raw.attendance_source_id AND prior_document.source_business_key = raw.source_business_key ) OR EXISTS ( SELECT 1 FROM evidence_link linked WHERE linked.raw_attendance_fact_id = raw.raw_attendance_fact_id ) THEN TRUE ELSE FALSE END AS hasTargetReportFact FROM raw_attendance_fact raw LEFT JOIN normalized_attendance_record normalized ON normalized.raw_attendance_fact_id = raw.raw_attendance_fact_id LEFT JOIN oa_attendance_document document ON document.normalized_attendance_record_id = normalized.normalized_attendance_record_id LEFT JOIN employee_match_decision matched ON matched.normalized_attendance_record_id = normalized.normalized_attendance_record_id LEFT JOIN employee employee ON employee.employee_id = matched.employee_id LEFT JOIN employee_version employee_history ON employee_history.employee_id = employee.employee_id WHERE raw.attendance_source_id = #{sourceId}
AND raw.source_business_key IN
#{key}
AND 1 = 0
ORDER BY raw.source_business_key, raw.raw_attendance_fact_id, normalized.normalized_attendance_record_id, employee_history.employee_version_id

mapper.sql:
WITH ranked_document AS ( SELECT document.*, ROW_NUMBER() OVER ( PARTITION BY document.attendance_source_id, document.source_business_key ORDER BY document.knowledge_rank DESC, document.created_at DESC, document.oa_attendance_document_id DESC ) AS version_rank FROM oa_attendance_document document WHERE document.attendance_source_id = #{sourceId} AND document.created_at <= #{dataAsOf}
AND document.source_business_key IN
#{key}
AND 1 = 0
) SELECT latest.source_business_key AS sourceBusinessKey, latest.oa_attendance_document_id AS oaAttendanceDocumentId, latest.document_type AS documentType, latest.created_at AS createdAt, context.activation_decision AS activationDecision, context.overtime_type AS overtimeType, CASE WHEN EXISTS ( SELECT 1 FROM raw_attendance_fact raw JOIN evidence_link linked ON linked.raw_attendance_fact_id = raw.raw_attendance_fact_id WHERE raw.attendance_source_id = latest.attendance_source_id AND raw.source_business_key = latest.source_business_key ) THEN TRUE ELSE FALSE END AS hasIndependentEvidenceLink, CASE WHEN EXISTS ( SELECT 1 FROM attendance_report_oa_fact prior_fact JOIN oa_attendance_document prior_document ON prior_document.oa_attendance_document_id = prior_fact.oa_attendance_document_id WHERE prior_document.attendance_source_id = latest.attendance_source_id AND prior_document.source_business_key = latest.source_business_key AND (prior_fact.company_id IS NULL OR prior_fact.company_id != #{targetCompanyId} OR prior_fact.employee_id IS NULL OR matched.employee_id IS NULL OR prior_fact.employee_id != matched.employee_id) ) THEN TRUE ELSE FALSE END AS hasConflictingReportIdentity, CASE WHEN EXISTS ( SELECT 1 FROM attendance_report_oa_evidence_exclusion excluded WHERE excluded.company_id = #{targetCompanyId} AND excluded.employee_id = matched.employee_id AND excluded.attendance_source_id = latest.attendance_source_id AND excluded.source_business_key = latest.source_business_key AND excluded.source_version = latest.source_version AND excluded.oa_attendance_document_id = latest.oa_attendance_document_id AND excluded.knowledge_at <= #{dataAsOf} AND (excluded.reversed_at IS NULL OR excluded.reversed_at > #{dataAsOf}) ) THEN TRUE ELSE FALSE END AS hasApplicableReportExclusion, CASE WHEN EXISTS ( SELECT 1 FROM oa_attendance_document future_document WHERE future_document.attendance_source_id = latest.attendance_source_id AND future_document.source_business_key = latest.source_business_key AND future_document.created_at > #{dataAsOf} ) THEN TRUE ELSE FALSE END AS hasFutureDocument, CASE WHEN context.activation_decision = 'ACTIVATED' AND context.overtime_type IS NOT NULL THEN TRUE ELSE FALSE END AS hasConsumableOvertimeContext
, CASE WHEN latest.source_status IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING') OR (latest.source_status = 'UNKNOWN' AND latest.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$') THEN TRUE WHEN latest.source_status IN ('REVOKED', 'REJECTED', 'DRAFT') THEN FALSE ELSE NULL END AS hasConsumableSourceStatus , CASE WHEN latest.document_type = 'LEAVE' AND latest.source_status = 'DRAFT' AND NOT EXISTS ( SELECT 1 FROM oa_attendance_document history_document WHERE history_document.attendance_source_id = latest.attendance_source_id AND history_document.source_business_key = latest.source_business_key AND (history_document.source_status IS NULL OR history_document.source_status != 'DRAFT' OR history_document.document_type IS NULL OR history_document.document_type != 'LEAVE') ) THEN TRUE ELSE FALSE END AS hasOnlyExplicitDraftLeaveHistory , CASE WHEN EXISTS ( SELECT 1 FROM attendance_report_oa_fact any_fact JOIN oa_attendance_document fact_document ON fact_document.oa_attendance_document_id = any_fact.oa_attendance_document_id WHERE fact_document.attendance_source_id = latest.attendance_source_id AND fact_document.source_business_key = latest.source_business_key ) THEN TRUE ELSE FALSE END AS hasAnyReportFact
FROM ranked_document latest LEFT JOIN oa_attendance_document_context context ON context.oa_attendance_document_id = latest.oa_attendance_document_id LEFT JOIN employee_match_decision matched ON matched.normalized_attendance_record_id = latest.normalized_attendance_record_id WHERE latest.version_rank = 1 AND latest.document_type IN ('OVERTIME', 'PUNCH_CORRECTION' , 'LEAVE') ORDER BY latest.source_business_key

mapper.select:
SELECT DISTINCT scoped.employee_number
FROM (
    SELECT employee_id, employee_number FROM employee WHERE company_id = #{companyId}
    UNION ALL
    SELECT history.employee_id, history.employee_number FROM employee_version history
    JOIN employee ON employee.employee_id = history.employee_id
    WHERE employee.company_id = #{companyId}
) scoped



        WHERE scoped.employee_id IN

            #{employeeId}

        AND (SELECT COUNT(*) FROM employee membership
             WHERE membership.company_id = #{companyId} AND membership.employee_id IN

                 #{employeeId}

             AND NULLIF(TRIM(membership.employee_number), '') IS NOT NULL
             AND EXISTS (SELECT 1 FROM employee_version known_history
                         WHERE known_history.employee_id = membership.employee_id)
             AND NOT EXISTS (SELECT 1 FROM employee_version unknown_number
                             WHERE unknown_number.employee_id = membership.employee_id
                               AND NULLIF(TRIM(unknown_number.employee_number), '') IS NULL)
        ) = #{targetEmployeeCount}

    WHERE 1 = 0

SELECT raw.source_business_key AS sourceBusinessKey, raw.raw_attendance_fact_id AS rawAttendanceFactId, raw.fact_kind AS factKind, normalized.normalized_attendance_record_id AS normalizedAttendanceRecordId, normalized.validation_status AS validationStatus, normalized.record_kind AS recordKind, document.oa_attendance_document_id AS oaAttendanceDocumentId, document.document_type AS documentType, CASE WHEN document.attendance_source_id = raw.attendance_source_id AND document.source_business_key = raw.source_business_key AND document.source_version = raw.source_version THEN TRUE ELSE FALSE END AS documentIdentityConsistent, matched.match_status AS matchStatus, employee.employee_id AS employeeId, employee.company_id AS employeeCompanyId, employee.employee_number AS employeeNumber, employee_history.employee_number AS historicalEmployeeNumber, CASE WHEN EXISTS ( SELECT 1 FROM attendance_report_oa_fact prior_fact JOIN oa_attendance_document prior_document ON prior_document.oa_attendance_document_id = prior_fact.oa_attendance_document_id WHERE prior_fact.company_id = #{targetCompanyId} AND prior_document.attendance_source_id = raw.attendance_source_id AND prior_document.source_business_key = raw.source_business_key ) OR EXISTS ( SELECT 1 FROM evidence_link linked WHERE linked.raw_attendance_fact_id = raw.raw_attendance_fact_id ) THEN TRUE ELSE FALSE END AS hasTargetReportFact, raw.source_version AS sourceVersion, document.source_status AS sourceStatus, document.leave_serial AS leaveSerial, CASE WHEN EXISTS ( SELECT 1 FROM oa_attendance_document amendment WHERE amendment.attendance_source_id = raw.attendance_source_id AND amendment.document_type = 'LEAVE_REVOCATION' AND (NULLIF(TRIM(amendment.original_leave_serial), '') IS NULL OR TRIM(amendment.original_leave_serial) = TRIM(document.leave_serial)) ) OR EXISTS ( SELECT 1 FROM raw_attendance_fact amendment_raw LEFT JOIN normalized_attendance_record amendment_normalized ON amendment_normalized.raw_attendance_fact_id = amendment_raw.raw_attendance_fact_id LEFT JOIN oa_attendance_document amendment_document ON amendment_document.normalized_attendance_record_id = amendment_normalized.normalized_attendance_record_id AND amendment_document.document_type = 'LEAVE_REVOCATION' AND amendment_document.attendance_source_id = amendment_raw.attendance_source_id AND amendment_document.source_business_key = amendment_raw.source_business_key AND amendment_document.source_version = amendment_raw.source_version WHERE amendment_raw.attendance_source_id = raw.attendance_source_id AND amendment_raw.source_business_key LIKE 'LEAVE_REVOCATION:%' AND amendment_document.oa_attendance_document_id IS NULL ) THEN TRUE ELSE FALSE END AS hasRelatedRevocation FROM raw_attendance_fact raw LEFT JOIN normalized_attendance_record normalized ON normalized.raw_attendance_fact_id = raw.raw_attendance_fact_id LEFT JOIN oa_attendance_document document ON document.normalized_attendance_record_id = normalized.normalized_attendance_record_id LEFT JOIN employee_match_decision matched ON matched.normalized_attendance_record_id = normalized.normalized_attendance_record_id LEFT JOIN employee employee ON employee.employee_id = matched.employee_id LEFT JOIN employee_version employee_history ON employee_history.employee_id = employee.employee_id WHERE raw.attendance_source_id = #{sourceId} AND raw.source_business_key IN
#{key}
ORDER BY raw.source_business_key, raw.raw_attendance_fact_id, normalized.normalized_attendance_record_id, employee_history.employee_version_id

SELECT raw.source_business_key AS sourceBusinessKey, raw.raw_attendance_fact_id AS rawAttendanceFactId, raw.fact_kind AS factKind, normalized.normalized_attendance_record_id AS normalizedAttendanceRecordId, normalized.validation_status AS validationStatus, normalized.record_kind AS recordKind, document.oa_attendance_document_id AS oaAttendanceDocumentId, document.document_type AS documentType, CASE WHEN document.attendance_source_id = raw.attendance_source_id AND document.source_business_key = raw.source_business_key AND document.source_version = raw.source_version THEN TRUE ELSE FALSE END AS documentIdentityConsistent, matched.match_status AS matchStatus, employee.employee_id AS employeeId, employee.company_id AS employeeCompanyId, employee.employee_number AS employeeNumber, employee_history.employee_number AS historicalEmployeeNumber, CASE WHEN EXISTS ( SELECT 1 FROM attendance_report_oa_fact prior_fact JOIN oa_attendance_document prior_document ON prior_document.oa_attendance_document_id = prior_fact.oa_attendance_document_id WHERE prior_fact.company_id = #{targetCompanyId}
AND prior_fact.employee_id IN
#{employeeId}
AND 1 = 0
AND prior_document.attendance_source_id = raw.attendance_source_id AND prior_document.source_business_key = raw.source_business_key ) OR EXISTS ( SELECT 1 FROM evidence_link linked WHERE linked.raw_attendance_fact_id = raw.raw_attendance_fact_id ) THEN TRUE ELSE FALSE END AS hasTargetReportFact, raw.source_version AS sourceVersion, document.source_status AS sourceStatus, document.leave_serial AS leaveSerial, CASE WHEN EXISTS ( SELECT 1 FROM oa_attendance_document amendment WHERE amendment.attendance_source_id = raw.attendance_source_id AND amendment.document_type = 'LEAVE_REVOCATION' AND (NULLIF(TRIM(amendment.original_leave_serial), '') IS NULL OR TRIM(amendment.original_leave_serial) = TRIM(document.leave_serial)) ) OR EXISTS ( SELECT 1 FROM raw_attendance_fact amendment_raw LEFT JOIN normalized_attendance_record amendment_normalized ON amendment_normalized.raw_attendance_fact_id = amendment_raw.raw_attendance_fact_id LEFT JOIN oa_attendance_document amendment_document ON amendment_document.normalized_attendance_record_id = amendment_normalized.normalized_attendance_record_id AND amendment_document.document_type = 'LEAVE_REVOCATION' AND amendment_document.attendance_source_id = amendment_raw.attendance_source_id AND amendment_document.source_business_key = amendment_raw.source_business_key AND amendment_document.source_version = amendment_raw.source_version WHERE amendment_raw.attendance_source_id = raw.attendance_source_id AND amendment_raw.source_business_key LIKE 'LEAVE_REVOCATION:%' AND amendment_document.oa_attendance_document_id IS NULL ) THEN TRUE ELSE FALSE END AS hasRelatedRevocation FROM raw_attendance_fact raw LEFT JOIN normalized_attendance_record normalized ON normalized.raw_attendance_fact_id = raw.raw_attendance_fact_id LEFT JOIN oa_attendance_document document ON document.normalized_attendance_record_id = normalized.normalized_attendance_record_id LEFT JOIN employee_match_decision matched ON matched.normalized_attendance_record_id = normalized.normalized_attendance_record_id LEFT JOIN employee employee ON employee.employee_id = matched.employee_id LEFT JOIN employee_version employee_history ON employee_history.employee_id = employee.employee_id WHERE raw.attendance_source_id = #{sourceId}
AND raw.source_business_key IN
#{key}
AND 1 = 0
ORDER BY raw.source_business_key, raw.raw_attendance_fact_id, normalized.normalized_attendance_record_id, employee_history.employee_version_id

SELECT employee_number FROM employee WHERE company_id = #{companyId}
UNION
SELECT history.employee_number FROM employee_version history
JOIN employee ON employee.employee_id = history.employee_id
WHERE employee.company_id = #{companyId}

mapper.insert:
INSERT INTO employee_match_decision (
    employee_match_decision_id, normalized_attendance_record_id,
    match_status, match_reason, employee_id, employment_period_id,
    device_person_binding_id, resolver_snapshot_digest, created_at
) VALUES (
    #{employeeMatchDecisionId}, #{normalizedAttendanceRecordId},
    #{matchStatus}, #{matchReason}, #{employeeId},
    #{employmentPeriodId}, #{devicePersonBindingId},
    #{resolverSnapshotDigest}, #{createdAt}
)

mapper.select:
SELECT event.effective_attendance_event_id,
       event.company_id, event.employee_id, event.event_kind,
       event.normalized_direction, event.point_instant,
       event.interval_start, event.interval_end,
       event.canonical_digest, event.created_at
FROM effective_attendance_event event
WHERE event.company_id = #{companyId}
  AND event.employee_id = #{employeeId}
  AND event.point_instant BETWEEN #{windowStart} AND #{windowEnd}
  AND event.normalized_direction = #{normalizedDirection}
ORDER BY event.point_instant, event.effective_attendance_event_id

mapper.insert:
