INSERT INTO evidence_link (
    evidence_link_id, effective_attendance_event_id,
    raw_attendance_fact_id, normalized_attendance_record_id,
    employee_match_decision_id, link_type, created_at
) VALUES (
    #{evidenceLinkId}, #{effectiveAttendanceEventId},
    #{rawAttendanceFactId}, #{normalizedAttendanceRecordId},
    #{employeeMatchDecisionId}, #{linkType}, #{createdAt}
)

mapper.select:
SELECT COUNT(*)
FROM evidence_link
WHERE effective_attendance_event_id = #{effectiveAttendanceEventId}
  AND raw_attendance_fact_id = #{rawAttendanceFactId}

SELECT document.oa_attendance_document_id
FROM oa_attendance_document document
WHERE document.attendance_source_id = #{sourceId}
  AND document.source_business_key = #{sourceBusinessKey}
  AND document.source_version = #{sourceVersion}
LIMIT 1

SELECT COUNT(*)
FROM oa_attendance_document_context context
WHERE context.oa_attendance_document_id = #{oaAttendanceDocumentId}
